rows.note:
Defect: ValidityCheckingTrustManager.checkAnchorValidity walks the PRESENTED chain in order and throws at the first certificate that any given certificate issued when all such issuers are expired. With a cross-signed intermediate (same name and key issued by an expired given root R1 and by a valid given CA R2) presented as [leaf, I_byR1, I_byR2], the platform PKIX builder validates leaf -> I_byR2 -> R2 (R2 valid), but the walk stops at I_byR1, finds only R1 (expired) and throws CertificateExpiredException, so a backend whose certificate chains to a valid given private CA gets 502 CONNECT_FAILED. Contradicts FR-PROXY-022 (a private CA trusts the certificates it issued) and the docs sentence that a given certificate the chain does not end at 'affects no connection even when it is expired'. Control fr_PROXY_022_AC2_validCaThroughItsIntermediateIsReached ([leaf, I_byR2], same bundle) is green, so the fixture is sound. A fix must decide anchor validity on the path the platform actually validated (e.g. accept when ANY given anchor reachable from some presented cert along a signature-valid chain is valid, or build the path itself), without reopening the r1 hole (expired anchor reached only through an expired path must still fail; the AC-3 rows of this class stay green). Full test class source follows:

package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.snoworca.naruserve.RestApp;
import com.snoworca.naruserve.proxy.ProxyTlsTest.TlsBackend;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientRequest;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientResponse;
import com.snoworca.naruserve.testing.TestApp;
import java.io.Closeable;
import java.io.File;
import java.io.IOException;
import java.net.Socket;
import java.security.Principal;
import java.security.PrivateKey;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import javax.net.ssl.KeyManager;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.X509ExtendedKeyManager;
import org.junit.After;
import org.junit.AfterClass;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Loop-P r2 probes for trustCertificates: the given anchor's validity check must not be fooled by the order of the
 * chain the backend presents.
 */
public class LoopPTrustCertsR2Test {

    private static File dir;
    private static String oldRootPem;   // expired private root CA (given)
    private static String validCaPem;   // currently valid private CA (given, in the same bundle)
    private static X509Certificate intermediate; // valid now, issued by the expired root
    private static X509Certificate leaf;         // valid now, localhost/127.0.0.1, issued by the intermediate
    private static X509Certificate validCa;
    private static X509Certificate intermediateByValidCa; // same name and key as intermediate, issued by the valid CA
    private static PrivateKey leafKey;

    private final InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
    private final TestApp t = TestApp.create(adapter);
    private final RestApp app = t.app();
    private final List<Closeable> closeables = new ArrayList<>();
    private final List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());
    private boolean started;

    @BeforeClass
    public static void make() throws Exception {
        dir = java.nio.file.Files.createTempDirectory("lp-trust-r2").toFile();
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "oldroot", "-keyalg", "RSA", "-keysize", "2048",
                "-dname", "CN=LP Old Root", "-ext", "bc:c", "-startdate", "2000/01/01", "-validity", "2",
                "-keystore", "oldroot.p12");
        TestCertificates.keytool(dir, "-exportcert", "-rfc", "-alias", "oldroot", "-keystore", "oldroot.p12",
                "-file", "oldroot.pem");
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "validca", "-keyalg", "RSA", "-keysize", "2048",
                "-dname", "CN=LP Valid CA", "-ext", "bc:c", "-validity", "3", "-keystore", "validca.p12");
        TestCertificates.keytool(dir, "-exportcert", "-rfc", "-alias", "validca", "-keystore", "validca.p12",
                "-file", "validca.pem");
        // intermediate: key in int.p12, certificate issued by the expired root, valid now
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "int", "-keyalg", "RSA", "-keysize", "2048",
                "-dname", "CN=LP Intermediate", "-ext", "bc:c", "-validity", "3", "-keystore", "int.p12");
        TestCertificates.keytool(dir, "-certreq", "-alias", "int", "-keystore", "int.p12", "-file", "int.csr");
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "oldroot", "-keystore", "oldroot.p12",
                "-infile", "int.csr", "-outfile", "intcert.pem", "-ext", "bc:c", "-validity", "3");
        // the same intermediate key and name, also issued by the valid CA (a cross-signed intermediate)
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "validca", "-keystore", "validca.p12",
                "-infile", "int.csr", "-outfile", "intnew.pem", "-ext", "bc:c", "-validity", "3");
        // leaf: issued by the intermediate's key (self-signed int cert in int.p12 is enough to sign with keytool)
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "server", "-keyalg", "RSA", "-keysize", "2048",
                "-dname", "CN=localhost", "-validity", "3", "-keystore", "leaf.p12");
        TestCertificates.keytool(dir, "-certreq", "-alias", "server", "-keystore", "leaf.p12", "-file", "leaf.csr");
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "int", "-keystore", "int.p12", "-infile",
                "leaf.csr", "-outfile", "leaf.pem", "-ext", "SAN=dns:localhost,ip:127.0.0.1", "-validity", "3");

        oldRootPem = TestCertificates.read(new File(dir, "oldroot.pem"));
        validCaPem = TestCertificates.read(new File(dir, "validca.pem"));
        validCa = TestCertificates.parse(validCaPem);
        intermediate = TestCertificates.parse(TestCertificates.read(new File(dir, "intcert.pem")));
        intermediateByValidCa = TestCertificates.parse(TestCertificates.read(new File(dir, "intnew.pem")));
        leaf = TestCertificates.parse(TestCertificates.read(new File(dir, "leaf.pem")));
        leafKey = (PrivateKey) TestCertificates.load(new File(dir, "leaf.p12"))
                .getKey("server", TestCertificates.PASSWORD.toCharArray());
        // sanity of the fixture: the root is expired, the intermediate and the leaf are valid now
        try {
            TestCertificates.parse(oldRootPem).checkValidity();
            fail("the old root must be expired");
        } catch (java.security.cert.CertificateExpiredException expected) {
            // fixture ok
        }
        intermediate.checkValidity();
        leaf.checkValidity();
        leaf.verify(intermediate.getPublicKey());
        intermediate.verify(TestCertificates.parse(oldRootPem).getPublicKey());
    }

    @AfterClass
    public static void clean() {
        TestCertificates.delete(dir);
    }

    @After
    public void tearDown() throws IOException {
        if (started) {
            app.shutdown(2, TimeUnit.SECONDS);
        }
        for (Closeable c : closeables) {
            c.close();
        }
    }

    /** A server context that presents exactly {@code chain} (in that order) with the leaf's key. */
    private static SSLContext serving(final X509Certificate... chain) throws Exception {
        X509ExtendedKeyManager km = new X509ExtendedKeyManager() {
            @Override public String[] getClientAliases(String keyType, Principal[] issuers) { return null; }
            @Override public String chooseClientAlias(String[] keyType, Principal[] issuers, Socket socket) { return null; }
            @Override public String[] getServerAliases(String keyType, Principal[] issuers) { return new String[] {"server"}; }
            @Override public String chooseServerAlias(String keyType, Principal[] issuers, Socket socket) {
                return keyType.startsWith("RSA") ? "server" : null;
            }
            @Override public String chooseEngineServerAlias(String keyType, Principal[] issuers, SSLEngine engine) {
                return keyType.startsWith("RSA") ? "server" : null;
            }
            @Override public X509Certificate[] getCertificateChain(String alias) { return chain.clone(); }
            @Override public PrivateKey getPrivateKey(String alias) { return leafKey; }
        };
        SSLContext c = SSLContext.getInstance("TLS");
        c.init(new KeyManager[] {km}, null, null);
        return c;
    }

    private TlsBackend backend(SSLContext c) throws IOException {
        TlsBackend b = new TlsBackend(c);
        closeables.add(b);
        return b;
    }

    private ClientResponse mountAndGet(Proxy proxy) {
        app.use("/api", proxy);
        app.onError((error, req, res) -> errors.add(error));
        t.start();
        started = true;
        return adapter.send(ClientRequest.of("GET", "/api/x"));
    }

    private void assertConnectFailed(ClientResponse r, TlsBackend backend) {
        assertEquals("status (errors: " + errors + ")", 502, r.status());
        synchronized (errors) {
            assertEquals("errors: " + errors, 1, errors.size());
            assertTrue(errors.get(0) instanceof ProxyException);
            assertSame(ProxyException.Kind.CONNECT_FAILED, ((ProxyException) errors.get(0)).kind());
        }
        assertEquals("request bytes the backend read", 0, backend.requestBytes());
    }

    private void assertReached(ClientResponse r, TlsBackend backend) {
        String causes = "";
        for (Throwable e : errors) { for (Throwable c = e; c != null; c = c.getCause()) { causes += " <- " + c; } }
        assertEquals("status (errors:" + causes + ")", 200, r.status());
        assertEquals("ok", r.text());
        assertTrue("errors: " + errors, errors.isEmpty());
    }

    // FR-PROXY-022 AC-2 (control): the valid private CA trusts what it issued through the intermediate it issued,
    // presented [leaf, intermediateByValidCa], bundle {expired root, valid CA}: reached.
    @Test(timeout = 60000)
    public void fr_PROXY_022_AC2_validCaThroughItsIntermediateIsReached() throws Exception {
        TlsBackend b = backend(serving(leaf, intermediateByValidCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port())
                .trustCertificates(oldRootPem + validCaPem)), b);
    }

    // FR-PROXY-022 AC-2: a cross-signed intermediate. The backend presents [leaf, intermediate-by-expired-root,
    // intermediate-by-valid-CA] (same intermediate name and key). The platform PKIX builder finds the valid path
    // leaf -> intermediate-by-valid-CA -> valid CA (a given certificate), so the valid private CA trusts the
    // certificate issued under it and the request must be reached; the expired root in the bundle is a given
    // certificate the platform's chain does not end at (docs: it "affects no connection").
    @Test(timeout = 60000)
    public void fr_PROXY_022_AC2_aCrossSignedChainReachingTheValidGivenCaIsReachedDespiteAnExpiredGivenRoot()
            throws Exception {
        TlsBackend b = backend(serving(leaf, intermediate, intermediateByValidCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port())
                .trustCertificates(oldRootPem + validCaPem)), b);
    }

    // FR-PROXY-022 AC-3 (control): an expired given private root reached through a presented intermediate, chain
    // presented in order [leaf, intermediate], bundle {expired root, valid CA}: 502 CONNECT_FAILED.
    @Test(timeout = 60000)
    public void fr_PROXY_022_AC3_expiredRootThroughIntermediateInOrderIsConnectFailed() throws Exception {
        TlsBackend b = backend(serving(leaf, intermediate));
        assertConnectFailed(mountAndGet(Proxy.to("https://localhost:" + b.port())
                .trustCertificates(oldRootPem + validCaPem)), b);
    }

    // FR-PROXY-022 AC-3: the same expired given root must still give 502 CONNECT_FAILED when the backend puts the
    // other (valid) given CA certificate between the leaf and the intermediate: [leaf, validCa, intermediate]. The
    // platform PKIX builder reorders and validates leaf -> intermediate -> expired root (anchor validity unchecked by
    // PKIX), while the validity walk stops at validCa because it is a given certificate.
    @Test(timeout = 60000)
    public void fr_PROXY_022_AC3_expiredRootIsNotHiddenByAValidGivenCertInTheMiddleOfThePresentedChain()
            throws Exception {
        TlsBackend b = backend(serving(leaf, validCa, intermediate));
        assertConnectFailed(mountAndGet(Proxy.to("https://localhost:" + b.port())
                .trustCertificates(oldRootPem + validCaPem)), b);
    }

    // FR-PROXY-022 AC-3: the X509Certificate overload, same unordered chain
    @Test(timeout = 60000)
    public void fr_PROXY_022_AC3_expiredRootIsNotHiddenByAValidGivenCertInTheMiddle_certificateOverload()
            throws Exception {
        TlsBackend b = backend(serving(leaf, validCa, intermediate));
        assertConnectFailed(mountAndGet(Proxy.to("https://localhost:" + b.port())
                .trustCertificates(TestCertificates.parse(oldRootPem), validCa)), b);
    }

    // FR-PROXY-022 AC-4: malformed CERTIFICATE blocks throw IllegalArgumentException at the call
    @Test
    public void fr_PROXY_022_AC4_malformedBlocksThrowIllegalArgumentException() throws Exception {
        String body = validCaPem.substring(validCaPem.indexOf('\n') + 1, validCaPem.indexOf("-----END"));
        String b = "-----BEGIN CERTIFICATE-----\n", e = "-----END CERTIFICATE-----\n";
        String twoInOne = b + body.trim() + "\n" + leafBody() + e;
        String[] bad = {
            b + "Proc-Type: 4,ENCRYPTED\n\n" + body + e,
            b + body.replaceFirst("\n", "\f") + e,
            b + body.substring(0, 8) + "=" + body.substring(8) + e,
            validCaPem + b + body,
            twoInOne,
            b + e,
            b + "AAAAAA==\n" + e,
        };
        for (int i = 0; i < bad.length; i++) {
            try {
                Proxy.to("https://localhost:1").trustCertificates(bad[i]);
                fail("case " + i + " accepted");
            } catch (IllegalArgumentException expected) {
                // ok
            }
        }
    }

    private static String leafBody() throws Exception {
        return java.util.Base64.getMimeEncoder().encodeToString(leaf.getEncoded()) + "\n";
    }
}
